'use strict';
const $=s=>document.querySelector(s);
const fixtures={past:{id:'past',label:'Past',date:'04 OCT · FULL TIME',title:'Harbour FC v Riverside United',score:'2 – 1',clock:'FULL TIME',venue:'The Lantern',line:'The comeback worth revisiting.',goals:[{min:21,team:'riverside'},{min:58,team:'harbour'},{min:84,team:'harbour'}]},live:{id:'live',label:'Live',date:'11 OCT · DEMO REPLAY',title:'Harbour FC v Riverside United',score:'1 – 1',clock:'65′ · PAUSED',venue:'The Lantern',line:'Level on the score. Shifting on the pitch.',goals:[{min:18,team:'harbour'},{min:43,team:'riverside'}]},upcoming:{id:'upcoming',label:'Upcoming',date:'18 OCT · 19:45',title:'Riverside United v Harbour FC',score:'vs',clock:'UPCOMING',venue:'Riverside Park',line:'The next chapter is still unwritten.',goals:[]}};
let section='matches',filter='live',speaker='guide',selected='live',prefs={club:'neutral',depth:'simple'},threads={};
const names={guide:'Your Matchmate',match:'The match',harbour:'Harbour FC',riverside:'Riverside United',lantern:'The Lantern',park:'Riverside Park'};
const key=()=>speaker==='guide'?'guide':`${speaker}:${selected}`;
const escapeHTML=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function crest(team){return `<span class="crest ${team==='riverside'?'away':''}" aria-hidden="true">${team==='harbour'?'H':'R'}</span>`}
function catalog(){document.querySelectorAll('[data-section]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.section===section)));const f=fixtures[filter];if(section==='matches'){$('#catalog').innerHTML=`<div class="filters" aria-label="Match time">${Object.values(fixtures).map(x=>`<button data-filter="${x.id}" aria-pressed="${x.id===filter}">${x.label}</button>`).join('')}</div>${MatchWorkspace.fixture({attrs:`data-match="${f.id}" aria-label="Open ${f.label.toLowerCase()} match: ${f.title}"`,date:f.date,statusClass:f.id==='live'?'live':'',status:f.id==='live'?'<i class="dot"></i>65′':f.id==='past'?'FT':'PREVIEW',homeCrest:crest(f.id==='upcoming'?'riverside':'harbour'),home:f.id==='upcoming'?'Riverside United':'Harbour FC',score:f.score,clock:f.clock,awayCrest:crest(f.id==='upcoming'?'harbour':'riverside'),away:f.id==='upcoming'?'Harbour FC':'Riverside United',venue:f.venue,action:'Talk to this match ↗'})}<p class="catalog-caption">${f.line}</p>`}else{const ids=section==='clubs'?['harbour','riverside']:['lantern','park'];$('#catalog').innerHTML=ids.map(id=>`<button class="entity" data-entity="${id}">${section==='clubs'?crest(id):'<span class="stadium-icon" aria-hidden="true">▱</span>'}<span><strong>${names[id]}</strong><small>${({harbour:'A port town. A pressing game. A stubborn belief.',riverside:'Patient football, with a little edge.',lantern:'Home of Harbour FC · Since 1928',park:'Home of Riverside United · By the river'})[id]}</small></span><span>↗</span></button>`).join('')+'<p class="catalog-caption">Fictional identities, written for this concept.</p>'}}
function opening(){if(speaker==='guide')return prefs.club==='neutral'?"Good football gives you something to talk about. Let’s find your way in.\n\nThere’s a game balanced at 1–1, a comeback to revisit, and a rivalry with another chapter ahead. Where shall we start?":`You’re following ${names[prefs.club]} for this visit. I’ll keep things ${prefs.depth==='tactical'?'tactical':'clear and simple'}.\n\nWe can catch up on the live replay, revisit the last meeting, or look ahead. You can also hear from your club or its home ground.`;if(speaker==='match'){if(selected==='past')return 'I finished 2–1 to Harbour. But my story started with Riverside taking the lead.\n\nCome back to the 58th minute with me: that was when the comeback began.';if(selected==='upcoming')return 'I haven’t kicked off yet. Riverside host Harbour at Riverside Park on 18 October.\n\nWe can explore the styles, the venue, and what might matter. My result is still unwritten.';return 'Sixty-five minutes in. One goal each. Plenty left to ask.\n\nHarbour struck first; Riverside answered before half-time. Let’s look at how we got here.'}return ({harbour:'I’m Harbour. A club shaped by the docks, the weather, and a belief that you don’t wait for a game to come to you.\n\nAsk me about my pressing game, my roots, or this meeting with Riverside.',riverside:'I’m Riverside. I like a little patience on the ball, and a little impatience when a gap opens.\n\nAsk about my style, my rivalry with Harbour, or the next match.',lantern:'They call me The Lantern. Since 1928, I’ve been Harbour’s place to gather.\n\nMy West Stand sits close to the touchline. On a matchday, the game can feel wonderfully near. Shall I show you around?',park:'I’m Riverside Park. The river runs beside me; the football has a rhythm of its own.\n\nI’m home to Riverside United, and the setting for the upcoming meeting. Want to get to know the ground?'})[speaker]}
function prompts(){return speaker==='guide'?['Catch me up','Take me back','What’s coming next?']:speaker==='match'?(selected==='past'?['Where did it turn?','Show me the goals']:selected==='live'?['How did we get here?','What happens next?']:['What should I watch for?','Who will win?']):['Tell me your story',speaker==='harbour'||speaker==='riverside'?'How do you play?':'What makes you special?']}
function handoffs(){if(speaker==='guide')return '';return `<div class="handoffs">${(speaker==='match'?['harbour','riverside',selected==='upcoming'?'park':'lantern']:speaker==='harbour'?['lantern','match']:speaker==='riverside'?['park','match']:['match',speaker==='lantern'?'harbour':'riverside']).map(id=>`<button data-entity="${id}">Talk to ${id==='match'?'the match':names[id]} ↗</button>`).join('')}</div>`}
function render(){const f=fixtures[selected];$('#speaker-name').textContent=names[speaker];$('#speaker-subtitle').textContent=speaker==='guide'?'Your personal football guide':speaker==='match'?`${f.label} match · Fictional scenario`:'An imagined football voice';$('#avatar').textContent=({guide:'✳',match:'↗',harbour:'H',riverside:'R',lantern:'▱',park:'▱'})[speaker];$('#guide').hidden=speaker==='guide';$('#context').innerHTML=speaker==='guide'?`<div class="guide-scene"><div class="eyebrow">YOUR FOOTBALL. YOUR WAY IN.</div><h2>A little context.<br>A whole new conversation.</h2><p>${prefs.club==='neutral'?'Start anywhere. I’ll help you find the next story.':`Following ${names[prefs.club]} · ${prefs.depth==='tactical'?'Tactical detail':'Keep it simple'}`}</p></div>`:`<div class="context-strip"><div><strong>${f.title}</strong><small>${f.label} · ${f.clock} · ${f.venue}</small></div><button class="text-button" id="sources">View sources ↗</button></div>`;
if(!threads[key()])threads[key()]=[{text:opening(),user:false}];$('#thread').innerHTML=threads[key()].map(m=>MatchWorkspace.message(m.text,m.user,names[speaker].toUpperCase(),speaker==='guide'?'Based on this demo and your choices for this visit':speaker==='match'?'Source: synthetic fixture record · '+f.label:'Source: authored fictional club / ground profile')).join('')+handoffs();$('#suggestions').innerHTML=prompts().map(p=>`<button data-prompt="${escapeHTML(p)}">${p}</button>`).join('');$('#thread').scrollTop=$('#thread').scrollHeight;}
function open(id,fixture){speaker=id;if(fixture)selected=fixture;render();if(innerWidth<761)$('.conversation').scrollIntoView({behavior:'smooth',block:'start'});}
function answer(q){if(!prompts().includes(q)){threads[key()].push({text:q,user:true},{text:'This is a scripted design preview. Try one of the suggested questions to explore this conversation; free-form AI replies come in the working app.',user:false});render();return}if(speaker==='guide'){if(q==='Catch me up'){filter='live';catalog();open('match','live');return}if(q==='Take me back'){filter='past';catalog();open('match','past');return}if(q==='What’s coming next?'){filter='upcoming';catalog();open('match','upcoming');return}}let reply;
if(speaker==='match'){const f=fixtures[selected];if(q==='Show me the goals'||q==='How did we get here?')reply=f.goals.map(g=>`${g.min}′ — ${names[g.team]} score.`).join('\n')+`\n\nThat makes it ${f.goals.filter(g=>g.team==='harbour').length}–${f.goals.filter(g=>g.team==='riverside').length}${selected==='live'?' at the paused 65th minute': ' at full time'}.`;else if(q==='Where did it turn?')reply='Harbour equalised in the 58th minute and scored the winner in the 84th.\n\nThe equaliser is the natural turning point in this short record. Explaining the tactical cause would need more event detail than this sample contains.';else if(q==='What happens next?'||q==='Who will win?')reply=selected==='upcoming'?'The outcome is open. Harbour’s pressing could unsettle Riverside; Riverside’s patient passing could play through it. Those are possibilities based on their fictional styles, not a forecast. No lineup or result is known.':'At 65 minutes it’s 1–1. Either side could find the next goal. I only have the record up to this moment, so I can discuss possibilities without revealing or inventing the ending.';else if(q==='What should I watch for?')reply=prefs.depth==='tactical'?'Watch the first line of Harbour’s press against Riverside’s build-up. If Riverside draw that line forward, space may open behind it. This is a tactical scenario based on the authored club styles, not confirmed match events.':'Look for whether Harbour can win the ball early, or Riverside can pass around them. That clash of styles could shape the game. We don’t have confirmed lineups yet.';
}else if(q==='Tell me your story'||q==='What makes you special?'||q==='How do you play?'){reply=({harbour:q==='How do you play?'?'I prefer to press early and make opponents hurry. The trade-off? Space can open behind that pressure. That’s my authored identity; it doesn’t prove what happened in a particular match.':'My roots are in a fictional port community. The Lantern is my home, and showing up for each other is part of my character. Want to meet the ground that holds those stories?',riverside:q==='How do you play?'?'I favour patient passing, drawing opponents towards the ball before looking for a gap. Patience is useful only if it leads somewhere. This is my fictional playing identity, not a report of today’s tactics.':'I’m the other voice in this rivalry: a fictional riverside club with a thoughtful style and pride in doing things our way. Riverside Park is where my story feels most at home.',lantern:'My story begins in 1928, in this imagined football world. I’m Harbour’s home, with a West Stand close to the pitch.\n\nI like to think that closeness makes every shout feel part of the match. That last thought is atmosphere, not a measured fact.',park:'In this fictional world, I sit beside the river and belong to Riverside United. I host their upcoming meeting with Harbour.\n\nWe haven’t written a rich ground history yet. I’d rather leave room for that story than invent a famous night.'})[speaker]}
if(!reply)reply='This is a scripted design preview, so I can’t answer that freely yet. Try one of the suggested questions below to explore the intended experience. In the working app, this is where a grounded AI reply would appear.';
threads[key()].push({text:q,user:true},{text:reply,user:false});render();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.section){section=b.dataset.section;catalog()}if(b.dataset.filter){filter=b.dataset.filter;catalog()}if(b.dataset.match)open('match',b.dataset.match);if(b.dataset.entity)open(b.dataset.entity);if(b.dataset.prompt)answer(b.dataset.prompt);if(b.id==='sources'){const f=fixtures[selected];$('#evidence-content').innerHTML=`<p>Everything in this preview is fictional. These are authored demo records, not an external football feed.</p><ul><li><strong>Selected fixture:</strong> ${f.title}, ${f.date}, ${f.venue}.</li><li><strong>Match facts:</strong> ${f.goals.length?f.goals.map(g=>`${g.min}′ ${names[g.team]}`).join('; '):'No events or result. Kickoff is scheduled for 19:45.'}.</li><li><strong>Knowledge boundary:</strong> ${selected==='live'?'Paused at minute 65. No later events are present.':selected==='past'?'Completed record.':'Pre-match context only. Predictions are possibilities.'}</li><li><strong>Club and ground profiles:</strong> Fictional identities written for this concept. First-person atmosphere is creative narration.</li></ul>`;$('#evidence').showModal()}});
$('#guide').onclick=()=>open('guide');$('.wordmark').onclick=e=>{e.preventDefault();open('guide')};$('#composer').onsubmit=e=>{e.preventDefault();const q=$('#question').value.trim();if(q){$('#question').value='';answer(q)}};$('#preferences').onclick=()=>{$('#club').value=prefs.club;$('#depth').value=prefs.depth;$('#prefs').showModal()};$('#save-prefs').onclick=()=>{prefs={club:$('#club').value,depth:$('#depth').value};delete threads.guide;$('#prefs').close();open('guide')};$('#reset-prefs').onclick=()=>{prefs={club:'neutral',depth:'simple'};threads={};$('#prefs').close();open('guide')};catalog();render();
